script:
frappe.ui.form.on("Rental Booking", {
    setup(frm) {
        frm.set_query("equipment_unit", "items", function () {
            return {
                filters: {
                    current_status: "Available"
                }
            };
        });
    },

    refresh(frm) {
        frm.dashboard.add_indicator(
            frm.doc.status || "No Status",
            "blue"
        );

    },

    start_date(frm) {
        check_days(frm);
        calculate_amount(frm);
    },

    end_date(frm) {
        check_days(frm);
        calculate_amount(frm);
    }
});

function check_days(frm) {
    if (!frm.doc.start_date || !frm.doc.end_date) {
        return;
    }
    let start = frappe.datetime.str_to_obj(frm.doc.start_date);
    let end = frappe.datetime.str_to_obj(frm.doc.end_date);
    let days =Math.floor((end - start) / (1000 * 60 * 60 * 24)) + 1;
    if (days > 30) {
        frappe.show_alert({
            message: "Rental period is more than 30 days",
            indicator: "orange"
        });
    }
}

function calculate_amount(frm) {
    if (!frm.doc.start_date || !frm.doc.end_date) {
        return;
    }
    let start = frappe.datetime.str_to_obj(frm.doc.start_date);
    let end = frappe.datetime.str_to_obj(frm.doc.end_date);
    let days =Math.floor((end - start) / (1000 * 60 * 60 * 24)) + 1;

    (frm.doc.items || []).forEach(row => {
        let amount = (row.daily_rate || 0) * days;
        frappe.model.set_value(row.doctype,row.name,"line_days",days);

        frappe.model.set_value(row.doctype,row.name,"line_amount",amount);
    });
}

frappe.ui.form.on("Rental Booking", {
    refresh(frm) {
        if (frm.doc.status === "Checked Out") {
            frm.add_custom_button("Log Return", function () {
                show_return_dialog(frm);
            });
        }
        if (!frm.is_new()) {
            frm.add_custom_button("Transfer Handler", function () {
                transfer_handler(frm);
            });
        }
    }
});
function show_return_dialog(frm) {
    if (!frm.doc.items || !frm.doc.items.length) {
        frappe.msgprint("No rental items found.");
        return;
    }
    let fields = [];
    frm.doc.items.forEach((row, index) => {
        fields.push({fieldname: "condition_" + index,fieldtype: "Select",label: row.equipment_unit + " Check-in Condition",options: "New\nGood\nFair\nPoor\nDamaged",
            default: row.checkin_condition_grade || "New",reqd: 1
        });
    });
    fields.push({fieldname: "notes",fieldtype: "Small Text",label: "Notes"
    });
    let dialog = new frappe.ui.Dialog({
        title: "Log Return",
        fields: fields,
        primary_action_label: "Submit",
        primary_action(values) {
            let rank = {"New": 0,"Good": 1,"Fair": 2,"Poor": 3,"Damaged": 4};
            let grade_dropped = false;
            frm.doc.items.forEach((row, index) => {
                let checkout_grade =row.checkout_condition_grade;
                let checkin_grade =
                    values["condition_" + index];
                if (checkout_grade && checkin_grade && rank[checkin_grade] > rank[checkout_grade]) {
                    grade_dropped = true;
                }
            });
            if (grade_dropped && !values.notes) {
                frappe.msgprint("Notes are mandatory when the condition grade drops.");
                return;
            }
            frm.doc.items.forEach((row, index) => {
                frappe.model.set_value(row.doctype,row.name,"checkin_condition_grade",values["condition_" + index]);
            });
            frm.set_value("status", "Returned");
            frm.save().then(() => {
                dialog.hide();
                frappe.show_alert({message: "Return recorded successfully",indicator: "green"
                });
                frm.trigger("start_date");
            });
        }
    });
    dialog.show();
}
function transfer_handler(frm) {
    frappe.prompt(
        [
            {
                fieldname: "new_handler",
                fieldtype: "Link",
                label: "New Handler",
                options: "Yard Staff",
                reqd: 1
            }
        ],
        function(values) {
            frappe.confirm(
                "Transfer this booking to " +
                values.new_handler +
                "?",
                function() {
                    frappe.call({
                        method: "rentflow.api.transfer_handler",
                        args: {
                            booking_name: frm.doc.name,
                            handled_by: values.new_handler
                        },
                        callback: function(r) {
                            if (!r.exc) {
                                frappe.show_alert({
                                    message: "Handler transferred successfully",indicator: "green"
                                });

                                frm.reload_doc();
                            }
                        }
                    });
                }
            );
        },
        "Transfer Handler",
        "Transfer"
    );
}

frappe.ui.form.on("Rental Booking", {
    refresh(frm) {
        if (frappe.user_roles.includes("RF Manager")) {
            frm.set_df_property(
                "customer_phone",
                "hidden",
                0
            );
        } else {
            frm.set_df_property(
                "customer_phone",
                "hidden",
                1
            );
        }
    }
});
